import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:povarspravka/core/calculation/calculation_engine.dart';
import 'package:povarspravka/core/calculation/models/heat_process.dart';
import 'package:povarspravka/core/calculation/models/loss_group.dart';
import 'package:povarspravka/core/calculation/food_classifier.dart';
import 'package:povarspravka/data/masters_recipes.dart';
import 'package:povarspravka/presentation/providers/dish_provider.dart';
import 'support/reference_db.dart';
import 'reaudit_state_support.dart';
import 'audit3_state_test.dart' show Audit3FailStorage;
import 'audit3_core_test.dart' as a3;

void main(){TestWidgetsFlutterBinding.ensureInitialized();final evidence=<Map<String,dynamic>>[];
test('R01 ready database pair 10322 to 10323',()async{final ps=await loadAllReferenceProducts();final raw=ps.singleWhere((p)=>p.id==10322);final ready=ps.singleWhere((p)=>p.id==10323);final d=a3.dish(process:HeatProcess.boil,items:[a3.ing(item:raw)],weight:268.5);final r=CalculationEngine.calculate(d);final values=[r.per100gProtein,r.per100gFat,r.per100gCarbs,r.per100gKcal];print('AUDIT3_READY 10322 '+values.toString());evidence.add({'raw':raw.id,'cooked':ready.id,'yield':r.yieldGrams,'actual':values,'reference':[ready.protein,ready.fat,ready.carbs,ready.kcal]});expect(values,[2.97, 0.38, 25.51, 117.3]);});
test('R02 ready database pair 10289 to 10288',()async{final ps=await loadAllReferenceProducts();final raw=ps.singleWhere((p)=>p.id==10289);final ready=ps.singleWhere((p)=>p.id==10288);final d=a3.dish(process:HeatProcess.boil,items:[a3.ing(item:raw)],weight:275.2);final r=CalculationEngine.calculate(d);final values=[r.per100gProtein,r.per100gFat,r.per100gCarbs,r.per100gKcal];print('AUDIT3_READY 10289 '+values.toString());evidence.add({'raw':raw.id,'cooked':ready.id,'yield':r.yieldGrams,'actual':values,'reference':[ready.protein,ready.fat,ready.carbs,ready.kcal]});expect(values,[4.65, 1.12, 21.36, 114.1]);});
test('R03 ready database pair 174 to 245',()async{final ps=await loadAllReferenceProducts();final raw=ps.singleWhere((p)=>p.id==174);final ready=ps.singleWhere((p)=>p.id==245);final d=a3.dish(process:HeatProcess.boil,items:[a3.ing(item:raw)],weight:77.0);final r=CalculationEngine.calculate(d);final values=[r.per100gProtein,r.per100gFat,r.per100gCarbs,r.per100gKcal];print('AUDIT3_READY 174 '+values.toString());evidence.add({'raw':raw.id,'cooked':ready.id,'yield':r.yieldGrams,'actual':values,'reference':[ready.protein,ready.fat,ready.carbs,ready.kcal]});expect(values,[21.74, 15.58, 0.0, 227.3]);});
test('R04 ready database pair 13684 to 13685',()async{final ps=await loadAllReferenceProducts();final raw=ps.singleWhere((p)=>p.id==13684);final ready=ps.singleWhere((p)=>p.id==13685);final d=a3.dish(process:HeatProcess.stew,items:[a3.ing(item:raw)],weight:77.8);final r=CalculationEngine.calculate(d);final values=[r.per100gProtein,r.per100gFat,r.per100gCarbs,r.per100gKcal];print('AUDIT3_READY 13684 '+values.toString());evidence.add({'raw':raw.id,'cooked':ready.id,'yield':r.yieldGrams,'actual':values,'reference':[ready.protein,ready.fat,ready.carbs,ready.kcal]});expect(values,[24.67, 6.48, 0.0, 156.9]);});
test('R05 ready database pair 11965 to 11966',()async{final ps=await loadAllReferenceProducts();final raw=ps.singleWhere((p)=>p.id==11965);final ready=ps.singleWhere((p)=>p.id==11966);final d=a3.dish(process:HeatProcess.boil,items:[a3.ing(item:raw)],weight:86.2);final r=CalculationEngine.calculate(d);final values=[r.per100gProtein,r.per100gFat,r.per100gCarbs,r.per100gKcal];print('AUDIT3_READY 11965 '+values.toString());evidence.add({'raw':raw.id,'cooked':ready.id,'yield':r.yieldGrams,'actual':values,'reference':[ready.protein,ready.fat,ready.carbs,ready.kcal]});expect(values,[2.2, 0.12, 19.73, 88.7]);});
test('R06 ready database pair 14369 to 14374',()async{final ps=await loadAllReferenceProducts();final raw=ps.singleWhere((p)=>p.id==14369);final ready=ps.singleWhere((p)=>p.id==14374);final d=a3.dish(process:HeatProcess.fry,items:[a3.ing(item:raw)],weight:76.7);final r=CalculationEngine.calculate(d);final values=[r.per100gProtein,r.per100gFat,r.per100gCarbs,r.per100gKcal];print('AUDIT3_READY 14369 '+values.toString());evidence.add({'raw':raw.id,'cooked':ready.id,'yield':r.yieldGrams,'actual':values,'reference':[ready.protein,ready.fat,ready.carbs,ready.kcal]});expect(values,[27.29, 1.66, 0.0, 124.1]);});
test('R07 ready database pair 14369 to 14370',()async{final ps=await loadAllReferenceProducts();final raw=ps.singleWhere((p)=>p.id==14369);final ready=ps.singleWhere((p)=>p.id==14370);final d=a3.dish(process:HeatProcess.boil,items:[a3.ing(item:raw)],weight:92.7);final r=CalculationEngine.calculate(d);final values=[r.per100gProtein,r.per100gFat,r.per100gCarbs,r.per100gKcal];print('AUDIT3_READY 14369 '+values.toString());evidence.add({'raw':raw.id,'cooked':ready.id,'yield':r.yieldGrams,'actual':values,'reference':[ready.protein,ready.fat,ready.carbs,ready.kcal]});expect(values,[22.58, 1.47, 0.0, 103.6]);});
test('F01 Savarin is not fruit',()async{final ps=await loadAllReferenceProducts();final p=ps.singleWhere((p)=>p.id==16801);expect([LossGroup.flourBread,LossGroup.other],contains(FoodClassifier.classify(p)),reason:p.name);});
test('F02 six master cards have database group ids and finite calculations',()async{final ps=await loadAllReferenceProducts();final db={for(final p in ps)p.id:p};expect(MastersRecipesCatalog.recipes,hasLength(6));for(final m in MastersRecipesCatalog.recipes){final d=m.toDish();expect(d.customYieldGrams,m.expectedYieldGrams);expect(d.process,isNot(HeatProcess.legacy));final r=CalculationEngine.calculate(d);expect(r.cookedKcal.isFinite,isTrue);for(final i in d.ingredients){expect(i.product.groupId,db[i.product.id]!.groupId,reason:'${m.name} ${i.product.name}');}evidence.add({'master':m.name,'process':d.process.name,'weight':r.yieldGrams,'macros':[r.cookedProtein,r.cookedFat,r.cookedCarbs,r.cookedKcal]});}});
test('F03 production-wired explicit failure is propagated',()async{final s=Audit3FailStorage();final lib=SavedDishesNotifier(s);final n=DishNotifier(storage:s,savedDishesNotifier:lib);addTearDown(n.dispose);addTearDown(lib.dispose);await n.flushPendingSaves();n.addIngredient(beet,100);await expectLater(n.flushPendingSaves(),throwsA(isA<FileSystemException>()));expect(n.isDirty,isTrue);await expectLater(n.saveCurrentToLibrary(),throwsA(isA<FileSystemException>()));expect(n.lastPersistenceError,isA<FileSystemException>());expect(n.isDirty,isTrue);expect(lib.state,isEmpty);});
test('F04 edit before load plus failed save must remain dirty',()async{final s=Audit3FailStorage();final lib=SavedDishesNotifier(s);final n=DishNotifier(storage:s,savedDishesNotifier:lib);addTearDown(n.dispose);addTearDown(lib.dispose);n.addIngredient(beet,200);await expectLater(n.flushPendingSaves(),throwsA(isA<FileSystemException>()));expect(n.state.ingredients.single.weightGrams,200);print('AUDIT3_EARLY dirty=${n.isDirty}, error=${n.lastPersistenceError}');expect(n.isDirty,isTrue,reason:'Failed disk write must not establish clean snapshot from an edit made before load');});
test('F05 fractional carb precision control',(){expect(a3.macros(a3.dish(process:HeatProcess.cold,items:[a3.ing(item:a3.product(c:1.23),grams:137.3)]))[2],1.69);});
test('F06 master process heuristic must distinguish boiled meat from stock',(){const m=MasterRecipe(id:'a3',name:'Отварное мясо',standardCode:'audit',category:'audit',description:'audit',expectedYieldGrams:100,culinaryProcess:'Отваривание',ingredients:[]);expect(m.heatProcess,HeatProcess.boil);});
tearDownAll(()async{final out=Platform.environment['AUDIT3_OUT'];if(out!=null)await File('$out/followup_evidence.json').writeAsString(jsonEncode(evidence));});}
